import { environment } from '@castify/record-mv3/environment';
import { sanitizeUrl } from '@braintree/sanitize-url';

export const signInToExtension = (selectAccount = false) => {
  const url = new URL(environment.externalLinks.loginRedirects);
  selectAccount && url.searchParams.append('selectAccount', 'true');
  chrome.tabs.create({
    url: sanitizeUrl(url.href),
    active: true,
  });
};
