import { createBrowserLogger, IBrowserLogger } from '@cfy/fe-monitoring';

const KEEP_ALIVE_INTERVAL_MS = 1000;
const FRAME_TIMEOUT_MS = 900;

const logger: IBrowserLogger = createBrowserLogger('getWatermarkedStream');

export const getWatermarkedStream = async (
  stream: MediaStream,
  watermarkUrl: string,
): Promise<MediaStream> => {
  const watermark = await loadImage(watermarkUrl);

  const [videoTrack] = stream.getVideoTracks();
  if (!videoTrack) {
    logger.error('No video track found in the stream');
    return stream;
  }

  const { reader, writer, generator } = createTrackPipeline(videoTrack);
  const offscreenCanvas = new OffscreenCanvas(1, 1);

  processFrames(reader, writer, offscreenCanvas, watermark);

  return new MediaStream([...stream.getAudioTracks(), generator]);
};

const loadImage = async (url: string): Promise<HTMLImageElement> => {
  const img = new Image();
  img.src = url;
  await img.decode();
  return img;
};

const createTrackPipeline = (videoTrack: MediaStreamTrack) => {
  const processor = new MediaStreamTrackProcessor({ track: videoTrack });
  const generator = new MediaStreamTrackGenerator({ kind: 'video' });

  const reader = processor.readable.getReader();
  const writer = generator.writable.getWriter();

  return { reader, writer, generator };
};

const processFrames = async (
  reader: ReadableStreamDefaultReader<VideoFrame>,
  writer: WritableStreamDefaultWriter<VideoFrame>,
  canvas: OffscreenCanvas,
  watermark: HTMLImageElement,
) => {
  const ctx = canvas.getContext('2d')! as OffscreenCanvasRenderingContext2D;

  let isInitialized = false;
  let logoWidth = 0;
  let logoHeight = 0;
  let logoX = 0;
  let logoY = 0;
  let lastFrameTime = performance.now();
  let closed = false;

  // Emit a frame every 1s if no new frames arrive
  const keepAlive = setInterval(async () => {
    if (closed) return;
    const now = performance.now();
    if (now - lastFrameTime > FRAME_TIMEOUT_MS) {
      try {
        const newFrame = new VideoFrame(canvas, { timestamp: now * 1000 });
        await writer.write(newFrame);
        newFrame.close();
      } catch (err) {
        closed = true;
        clearInterval(keepAlive);
      }
    }
  }, KEEP_ALIVE_INTERVAL_MS);

  try {
    // eslint-disable-next-line no-constant-condition
    while (true) {
      const { value: frame, done } = await reader.read();
      if (done || closed) break;
      if (!frame) continue;

      try {
        if (!isInitialized) {
          canvas.width = frame.displayWidth;
          canvas.height = frame.displayHeight;

          logoWidth = canvas.width * 0.2;
          logoHeight = logoWidth * (watermark.height / watermark.width);
          logoX = canvas.width - logoWidth - 20;
          logoY = canvas.height - logoHeight - 20;

          isInitialized = true;
        }

        ctx.drawImage(frame, 0, 0, canvas.width, canvas.height);
        ctx.imageSmoothingEnabled = true;
        ctx.drawImage(watermark, logoX, logoY, logoWidth, logoHeight);

        const newFrame = new VideoFrame(canvas, { timestamp: frame.timestamp });
        await writer.write(newFrame);
        newFrame.close();

        lastFrameTime = performance.now();
      } catch (err) {
        // Possible writer closed mid-loop
        closed = true;
        clearInterval(keepAlive);
        break;
      } finally {
        frame.close();
      }
    }
  } finally {
    closed = true;
    clearInterval(keepAlive);
    try {
      await writer.close();
    } catch {
      // ignore if already closed
    }
  }
};
