export const AUDIO_BITRATE = 112000 as const;

export type BitratePreset = 'high' | 'medium' | 'low';

// Mapping of sqrt(w * h) to bitrate in MBps.
// Sorted list of [dimension, bitrate] defines
// what bitrate to use for the normalized dimension (sqrt(w * h)).
// E.g. [[0, 3], [720, 5]] means:
// use 3Mbps for videos less than 720x720px in size and 5Mbps for larger ones.
export type BitrateTable = ReadonlyArray<readonly [number, number]>;

// Mapping quality setting to bits per pixel.
export type BitratePresetTable = { [k in BitratePreset]: BitrateTable };

// Note: the bitrates all tables below have been thoroughly, but manually
// tuned via visual inspection across common resolutions and content types.
// Ideally we'd have an automated test set / benchmark using using some
// well-defined perceptive visual quality metric to come up with those values.
// A given quality setting is intended to yield compareable visual quality
// across codecs.
export const H264_BITRATE_PRESETS: BitratePresetTable = {
  high: [
    [0, 3],
    [720, 6],
    [1080, 7],
    [2000, 10],
  ],
  medium: [
    [0, 3],
    [720, 4.5],
    [1080, 2.5],
    [2000, 2.5],
  ],
  low: [
    [0, 1.5],
    [720, 1],
    [1080, 0.5],
    [2000, 0.3],
  ],
} as const;

