import { createBrowserLogger } from '@cfy/fe-monitoring';
import { IRecording } from '../../../state/recording.mst';
import { IRecordingSettings } from '../../../state/recordingSettings.mst';
import { navigateToTab } from '../../../util/recorder-helpers';
import { ControllerStorageDriver } from '../../storage/ControllerStorageDriver';
import { resizeTabTo } from '../../../components/RightSettingsDrawer/utils/resizeTab';
import { Resolution } from '@castify/record-mv3/common';
import { getWatermarkedStream } from './getWatermarkedStream';

export interface TabIds {
  activeTabId: number;
  controllerTabId: number;
}

const logger = createBrowserLogger('RecordingManager');

export interface RecordingManagerStrategy {
  getMediaStreamId: (tabIds: TabIds) => Promise<string | null>;
  getCombinedMediaStream: (
    streamId: string,
    resolution?: Resolution,
  ) => Promise<MediaStream>;
  navigateToConsumingTab: (tabIds: TabIds) => Promise<void>;
}

export class RecordingManager {
  constructor(
    private recordingSettings: IRecordingSettings,
    private recordingId: string,
    private strategy: RecordingManagerStrategy,
  ) {}

  get type() {
    return this.recordingSettings.recordingType;
  }

  // The purpose of this function is to pre-detect and correct odd window sizes.
  // The extension API for recording the video is not capable of handling odd
  // width or height values. (See navigator.mediaDevices.getUserMedia)
  // This means that if you tell it to record at 2304x1089, it will actually round
  // down to the nearest even value: 2304x1088.
  // This is an issue because now the window has 1 more row of pixels than the recorder
  // is able to capture.
  // In response, the recorder adds a 1px black column on the right side of the video
  // so that it can fit all 1089 vertical pixels into a 1088 height box.
  // This is not the desired outcome, so we must correct it before the recording starts.
  async getNormalizedTabResolution(tabId: number): Promise<Resolution> {
    const tab = await chrome.tabs.get(tabId);
    if (!tab.width || !tab.height) {
      logger.warn('Tab unexpectedly has no height or width');
      return { width: 0, height: 0 };
    }

    const isWidthOdd = tab.width % 2 === 1;
    const isHeightOdd = tab.height % 2 === 1;
    if (!isWidthOdd && !isHeightOdd) {
      return { width: tab.width, height: tab.height };
    }

    const normalizedWidth = tab.width - (isWidthOdd ? 1 : 0);
    const normalizedHeight = tab.height - (isHeightOdd ? 1 : 0);
    await resizeTabTo(tabId, normalizedWidth, normalizedHeight);

    return { width: normalizedWidth, height: normalizedHeight };
  }

  async startRecording({
    recording,
    tabIds,
    onComplete,
    onDeleted,
    onNewDataAvailable,
    shouldCountIn,
    tabWasManuallyChanged,
  }: {
    recording: IRecording;
    tabIds: TabIds;
    onComplete: (forceStopped?: boolean) => void;
    onDeleted: () => void;
    onNewDataAvailable: (
      duration: number,
      mimeType: string,
      title: string,
      orgId?: string,
    ) => void;
    shouldCountIn: boolean;
    tabWasManuallyChanged?: boolean;
  }): Promise<MediaStream | undefined> {
    try {
      if (!tabWasManuallyChanged) {
        await this.navigateToConsumingTab(tabIds);
      }

      const {
        recordingType,
        selectedResolution,
        getSelectedResolution,
        useWatermark,
      } = this.recordingSettings;

      const isTabRecording = recordingType === 'tab';
      const isDesktopRecording = recordingType === 'desktop';

      let resolution: Resolution | undefined = undefined;
      if (
        selectedResolution !== 'OFF' &&
        (isTabRecording || isDesktopRecording)
      ) {
        resolution = getSelectedResolution();
      } else if (selectedResolution === 'OFF' && isTabRecording) {
        resolution = await this.getNormalizedTabResolution(tabIds.activeTabId);
      }

      ControllerStorageDriver.setRecorderStatus('acquiring-media');

      // Applying watermark only works if the Controller tab is focused during capture
      if (isTabRecording && useWatermark)
        navigateToTab(String(tabIds.controllerTabId));
      const streamId = await this.getMediaStreamId(tabIds);
      if (isTabRecording && useWatermark)
        navigateToTab(String(tabIds.activeTabId));

      if (streamId === null) {
        // could not or chose not to share screen, navigate back to active tab and reset status
        await navigateToTab(String(tabIds.activeTabId));
        ControllerStorageDriver.setRecorderStatus('stopped');
        await chrome.runtime.sendMessage({
          command: 'VIDEO_OFF',
          payload: {},
          target: 'offscreen',
        });
        window.close();
        return;
      }

      //forcefully using as string here because we should have broken execution on above condition if null
      const fullStream = await this.getCombinedMediaStream(
        streamId as string,
        resolution,
      );

      let combinedStream = fullStream;
      if (useWatermark) {
        combinedStream = await getWatermarkedStream(
          fullStream,
          chrome.runtime.getURL('assets/images/castify-watermark.png'),
        );
      }

      // custom events emitted from desktop streams. Stops recording
      // if the user stops sharing their screen
      combinedStream.addEventListener('track ended', () => {
        this.stopRecording(recording);
      });

      recording.setMediaStream(combinedStream);
      recording.createMediaRecorder(
        this.type,
        this.recordingSettings.bitrate,
        onComplete,
        onDeleted,
        onNewDataAvailable,
      );

      logger.info(`About to start ${this.type} recording`, {
        applicationState: {
          recordingType: this.type,
          recordingId: this.recordingId,
        },
      });
      if (this.type === 'desktop') {
        await navigateToTab(String(tabIds.activeTabId));

        // if user selects "window" mode, turn off PIP
        const track = combinedStream.getVideoTracks()[0];
        const settings = track.getSettings();
        if (settings.displaySurface === 'window') {
          this.recordingSettings.setPipEnabled(false);
          chrome.runtime.sendMessage({
            command: 'STOP_PIP',
          });
        }
      }

      if (shouldCountIn) {
        recording.setRecorderState('counting-in');
        chrome.runtime.sendMessage({
          command: 'start-countdown',
          payload: {
            duration: this.recordingSettings.countInDuration,
          },
        });
      } else {
        recording.start();
      }
      return combinedStream;
    } catch (e: unknown) {
      // TODO: while this should have proper error handling,
      // this is to give context on the logs for an error we keep getting
      if (e instanceof Error && e.message === 'Requested device not found') {
        // This is for getting context on
        let devices: MediaDeviceInfo[] = [];
        try {
          devices = await navigator.mediaDevices.enumerateDevices();
        } catch (noDevicesError) {
          devices = [];
        }

        const selectedAudioDevice =
          this.recordingSettings.selectedAudioDeviceId;
        const selectedVideoDevice =
          this.recordingSettings.selectedVideoDeviceId;

        const audioDeviceInDevices = devices.some(
          ({ deviceId }) => deviceId === selectedAudioDevice,
        );
        const videoDeviceInDevices = devices.some(
          ({ deviceId }) => deviceId === selectedVideoDevice,
        );

        logger.error(
          `Requested device not found,
          \n devices: ${JSON.stringify(devices)}
          \n selectedAudioDevice: ${
            selectedAudioDevice ?? 'undefined'
          } selectedVideoDevice: ${selectedVideoDevice ?? 'undefined'}
          \n audioDeviceIsInDevices: ${audioDeviceInDevices}
          \n videoDeviceIsInDevices: ${videoDeviceInDevices}
          `,
        );
      }
      // Always throw the error regardless.
      throw e;
    }
  }

  immediateStart(recording: IRecording) {
    logger.info('skipping to starting recording right away recording', {
      applicationState: {
        recordingType: this.type,
        recordingId: this.recordingId,
      },
    });
    recording.start();
  }
  stopRecording(recording: IRecording) {
    logger.info('stopping recording', {
      applicationState: {
        recordingType: this.type,
        recordingId: this.recordingId,
      },
    });
    recording.stop();
  }

  pauseRecording(recording: IRecording) {
    logger.info('pausing recording', {
      applicationState: {
        recordingType: this.type,
        recordingId: this.recordingId,
      },
    });
    recording.pause();
  }

  resumeRecording(recording: IRecording) {
    logger.info('resuming recording', {
      applicationState: {
        recordingType: this.type,
        recordingId: this.recordingId,
      },
    });
    recording.resume();
  }

  deleteRecording(recording: IRecording) {
    logger.info('deleting recording', {
      applicationState: {
        recordingType: this.type,
        recordingId: this.recordingId,
      },
    });
    recording.delete();
  }

  async restartRecording(recording: IRecording, shouldCountIn: boolean) {
    recording.restart();

    //since restart resets the state of the recording to initalized it skips the acquiring media phase of our state machine
    //this line kicks it back into that state so our controller tab won't close before it can actually restart
    ControllerStorageDriver.setRecorderStatus('acquiring-media');
    if (shouldCountIn) {
      recording.setRecorderState('counting-in');
      chrome.runtime.sendMessage({
        command: 'start-countdown',
        payload: {
          duration: this.recordingSettings.countInDuration,
        },
      });
    } else {
      recording.start();
    }
  }

  getMediaStreamId(tabIds: TabIds) {
    return this.strategy.getMediaStreamId(tabIds);
  }

  getCombinedMediaStream(streamId: string, resolution?: Resolution) {
    return this.strategy.getCombinedMediaStream(streamId, resolution);
  }

  navigateToConsumingTab(tabIds: TabIds) {
    return this.strategy.navigateToConsumingTab(tabIds);
  }
}
