import { Instance, applySnapshot, types } from 'mobx-state-tree';
import {
  IRecordingInProgress,
  RecordingInProgress,
} from './recordingInProgress.mst';
import { IRecordingSettings, RecordingSettings } from './recordingSettings.mst';
import { UserState } from './userState.mst';
import { UploadingInProgress } from './uploadingInProgress.mst';
import { RecordingStore } from './recordingStore.mst';
import { deleteRecordingDB } from '@castify/record-mv3/recording-indexed-db';
import { ControllerStorageDriver } from '../controller/storage/ControllerStorageDriver';
/**
 * State, views, & actions backing  the Debugger.
 */

export const ControllerState = types
  .model('ControllerState', {
    recorderStatus: types.optional(
      types.union(
        types.literal('initialized'),
        types.literal('acquiring-media'),
        types.literal('counting-in'),
        types.literal('recording'),
        types.literal('paused'),
        types.literal('stopped'),
        types.literal('error'),
        types.literal(undefined),
      ),
      'initialized',
    ),
    recordingSettings: types.optional(RecordingSettings, {}),
    recordingInProgress: types.optional(RecordingInProgress, {}),
    recordingStore: types.optional(RecordingStore, {}),
    uploadingInProgress: types.optional(UploadingInProgress, {}),
    userState: types.optional(UserState, {}),
  })
  .views((self) => {
    return {
      isRecording() {
        if (!self.recorderStatus) return false;
        const recordingContext = [
          'acquiring-media',
          'counting-in',
          'recording',
          'paused',
        ];
        return recordingContext.includes(self.recorderStatus);
      },
      isInCountdown() {
        return (
          self.recorderStatus === 'acquiring-media' ||
          self.recorderStatus === 'counting-in'
        );
      },
      get videoCount() {
        const {
          userState: { castVideoCount },
          recordingStore: { recordingList },
        } = self;
        return castVideoCount + recordingList.length;
      },
      /** Expected to return `true` when user data unavailable. */
      get willExceedVideoLimit() {
        const {
          userState: { hasUserData, videoLimit, userCastLimit },
        } = self;
        const hasUnlimitedVideoLimit = userCastLimit === -1;
        return hasUserData
          ? hasUnlimitedVideoLimit
            ? false
            : this.videoCount + 1 > videoLimit
          : true;
      },
    };
  })
  .actions((self) => {
    return {
      setRecordingSettings(settings: IRecordingSettings) {
        self.recordingSettings = settings;
      },
      setRecordingRecordingInProgress(
        recordingInProgress: IRecordingInProgress,
      ) {
        self.recordingInProgress = recordingInProgress;
      },
      async setRecorderStatus(
        value:
          | 'initialized'
          | 'acquiring-media'
          | 'counting-in'
          | 'recording'
          | 'paused'
          | 'stopped'
          | 'error',
      ) {
        self.recorderStatus = value;
      },
      async reset() {
        await deleteRecordingDB();
        await ControllerStorageDriver.deleteControllerState();
        applySnapshot(self, {});
      },
    };
  });

export type IControllerState = Instance<typeof ControllerState>;
