interface ExternalLinks {
  authentication: string;
  loginRedirects: string;
  myVideosPage: string;
  cartPage: string;
  extensionIntake: string;
  installationRedirect: string;
  forceConsentSignIn: string;
  umbrellaServiceUrl: string;
  blockedPermissionsSupportLink: string;
  blockedRecordingToolsSupportLink: string;
  recordVideoSupportLink: string;
  supportPage: string;
  uninstallUrl: string;
  pricingPage: string;
  accountPage: string;
  manageVideoPage: string;
  blogPage: string;
  submitPage: string;
  googleDriveV3: string;
  googleDriveUploadV3: string;
  googleDriveUploadV2: string;
  homePage: string;
}

interface FirebaseConfig {
  apiKey: string;
  authDomain: string;
  databaseURL: string;
  projectId: string;
  storageBucket: string;
  messagingSenderId: string;
  appId: string;
  measurementId: string;
}

/**
 * These are the properties that are passed in when instantiating
 * the ExtensionEnvironment. They are set individually as readonly
 * properties on the instance
 */
type ExtensionEnvironmentDefinition = Pick<
  ExtensionEnvironment,
  | 'isObservabilityEnabled'
  | 'production'
  | 'environmentName'
  | 'extensionId'
  | 'extensionOrigin'
  | 'webAppUrl'
  | 'logServiceUrl'
  | 'studioServiceUrl'
  | 'featuresServiceUrl'
  | 'contentServiceUrl'
  | 'authServiceUrl'
  | 'licensingServiceUrl'
  | 'userServiceUrl'
  | 'notificationsServiceUrl'
  | 'watchPageUrl'
  | 'otelCollectorUrl'
  | 'editUrl'
  | 'firebaseConfig'
>;

export class ExtensionEnvironment implements ExtensionEnvironmentDefinition {
  readonly isObservabilityEnabled?: boolean =
    this.definition.isObservabilityEnabled;
  readonly production: boolean = this.definition.production;
  readonly environmentName: string = this.definition.environmentName;
  readonly extensionId: string = this.definition.extensionId;
  readonly extensionOrigin: string = this.definition.extensionOrigin;
  readonly webAppUrl: string = this.definition.webAppUrl;
  readonly logServiceUrl: string = this.definition.logServiceUrl;
  readonly studioServiceUrl: string = this.definition.studioServiceUrl;
  readonly featuresServiceUrl: string = this.definition.featuresServiceUrl;
  readonly contentServiceUrl: string = this.definition.contentServiceUrl;
  readonly authServiceUrl: string = this.definition.authServiceUrl;
  readonly userServiceUrl: string = this.definition.userServiceUrl;
  readonly licensingServiceUrl: string = this.definition.licensingServiceUrl;
  readonly notificationsServiceUrl: string =
    this.definition.notificationsServiceUrl;
  readonly watchPageUrl: string = this.definition.watchPageUrl;
  readonly otelCollectorUrl: string = this.definition.otelCollectorUrl;
  readonly editUrl: string = this.definition.editUrl;
  readonly firebaseConfig: FirebaseConfig = this.definition.firebaseConfig;

  public externalLinks: ExternalLinks;

  constructor(private definition: ExtensionEnvironmentDefinition) {
    this.externalLinks = {
      loginRedirects: `${this.webAppUrl}/extension-auth/handover`,
      authentication: `${this.webAppUrl}/manage/empty`,
      manageVideoPage: `${this.webAppUrl}/manage/videos`,
      homePage: `${this.webAppUrl}/home`,
      myVideosPage: `${this.webAppUrl}/videos`,
      cartPage: `${this.webAppUrl}/cart`,
      extensionIntake: `${this.webAppUrl}/manage/videos/new?source=extension`,
      installationRedirect: `${this.webAppUrl}/analytics/ext-install-event`,
      forceConsentSignIn: `${this.webAppUrl}/signin?forceConsent=true`,
      umbrellaServiceUrl: `https://umbrella.svc.${
        this.production
          ? 'screencastify.com'
          : `${this.environmentName}.screencastify.com`
      }/api/umbrellaService`,
      blockedPermissionsSupportLink:
        'https://askcastify.zendesk.com/hc/en-us/articles/7589057200023-I-Accidentally-Blocked-Screencastify-from-Accessing-my-Webcam-and-Microphone',
      blockedRecordingToolsSupportLink:
        'https://askcastify.zendesk.com/hc/en-us/articles/7148797038231',
      supportPage: `${this.webAppUrl}/support`,
      recordVideoSupportLink:
        'https://learn.screencastify.com/hc/en-us/articles/360049302954-How-to-make-your-first-recording',
      uninstallUrl: `${this.webAppUrl}/analytics/ext-uninstall-event`,
      pricingPage: 'https://www.screencastify.com/pricing',
      accountPage: `${this.webAppUrl}/account`,
      blogPage: 'https://www.screencastify.com/blog',
      submitPage: `${this.webAppUrl}/submit`,
      googleDriveV3: 'https://www.googleapis.com/drive/v3',
      googleDriveUploadV3: 'https://www.googleapis.com/upload/drive/v3',
      googleDriveUploadV2: 'https://www.googleapis.com/upload/drive/v2',
    };
  }
}
